SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icu_los, i.in_hospital_mortality_rate, percentile_cont(0.25) within GROUP (ORDER BY p.procedure_count) AS q25, percentile_cont(0.5) within GROUP (ORDER BY p.procedure_count) AS q50, percentile_cont(0.9) within GROUP (ORDER BY p.procedure_count) AS q90 FROM patients p JOIN icustays i ON p.subject_id = i.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 50 AND 60 AND p.anchor_year_group = 'Intracranial hemorrhage' AND i.intime <= '2020-01-01' AND (i.outtime >= '2020-01-01' OR i.outtime IS NULL) AND (p.dod >= '2020-01-01' OR p.dod IS NULL) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icu_los, i.in_hospital_mortality_rate;